import { useState, useEffect } from 'react';
const API = 'http://localhost:5000/api';
const getToken = () => localStorage.getItem('examai_token');

const STAT_COLORS = ['#6d28d9','#16a34a','#2563eb','#d97706','#7c3aed'];

export default function AdminDashboard({ store, setActivePage }) {
  const [stats,   setStats]   = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => { load(); }, []);

  const apiFetch = async (path) => {
    const res = await fetch(`${API}${path}`, { headers:{ Authorization:`Bearer ${getToken()}` } });
    return res.json();
  };

  const load = async () => {
    try {
      setLoading(true);
      const [analyticsData, studentsData] = await Promise.all([apiFetch('/analytics'), apiFetch('/students')]);
      const exams    = analyticsData?.exams||[];
      const subs     = analyticsData?.submissions||[];
      const students = Array.isArray(studentsData)?studentsData:[];
      const results  = subs.filter(s=>s.total_score!==null);
      const avgScore = results.length?(results.reduce((a,r)=>a+Number(r.total_score),0)/results.length).toFixed(1):0;
      const passRate = results.length?Math.round(results.filter(r=>r.grade&&r.grade!=='F').length/results.length*100):0;
      const qCounts  = {};
      await Promise.all(exams.map(async e => { const qs=await apiFetch(`/questions/${e.exam_id}`); qCounts[e.exam_id]=Array.isArray(qs)?qs.length:0; }));
      const totalQ = Object.values(qCounts).reduce((a,b)=>a+b,0);
      setStats({ exams, subs, students, avgScore, passRate, qCounts, totalQ });
    } catch(e) { console.error(e); }
    finally { setLoading(false); }
  };

  const STATS_DEF = stats ? [
    { label:'TOTAL EXAMS',  value:stats.exams.length,    sub:'Created by you',   color:'#6d28d9' },
    { label:'STUDENTS',     value:stats.students.length,  sub:'Took your exams',  color:'#16a34a' },
    { label:'SUBMISSIONS',  value:stats.subs.length,      sub:'Completed exams',  color:'#2563eb' },
    { label:'QUESTIONS',    value:stats.totalQ,           sub:'In your exams',    color:'#d97706' },
    { label:'AVG SCORE',    value:stats.avgScore,         sub:'Points',           color:'#7c3aed' },
    { label:'PASS RATE',    value:`${stats.passRate}%`,   sub:'Grade D or above', color:'#16a34a' },
  ] : [];

  return (
    <div className="fade-up">
      {/* Hero — matches Image 1 */}
      <div style={{ marginBottom:32 }}>
        <div style={{ display:'inline-flex', alignItems:'center', background:'rgba(109,40,217,0.08)', border:'1px solid #ddd6fe', borderRadius:20, padding:'3px 14px', fontSize:11, fontWeight:600, color:'#7c3aed', marginBottom:14, letterSpacing:.5, fontFamily:'Inter,sans-serif' }}>
          ADMIN PANEL
        </div>
        <h1 style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:900, fontSize:42, color:'#0f0f1a', marginBottom:12, letterSpacing:-1, lineHeight:1.1 }}>
          Welcome back,
        </h1>
        <p style={{ fontSize:13, color:'#6b7280', marginBottom:24, lineHeight:1.7, fontFamily:'JetBrains Mono,monospace', maxWidth:500 }}>
          Manage exams, generate AI questions, and track student<br/>performance.
        </p>
        <div style={{ display:'flex', gap:12 }}>
          <button onClick={() => setActivePage('create-exam')}
            style={{ padding:'12px 28px', background:'#5b21b6', color:'#fff', borderRadius:12, border:'none', fontWeight:700, fontSize:14, cursor:'pointer', display:'flex', alignItems:'center', gap:8, fontFamily:'JetBrains Mono,monospace', letterSpacing:.3 }}>
            + Create New Exam
          </button>
          <button onClick={() => setActivePage('analytics')}
            style={{ padding:'12px 24px', background:'#fff', color:'#374151', borderRadius:12, border:'1px solid #e5e7eb', fontWeight:700, fontSize:14, cursor:'pointer', display:'flex', alignItems:'center', gap:8 }}>
            <span style={{ fontSize:16 }}>📊</span> View Analytics
          </button>
        </div>
      </div>

      {/* Stat cards — matches Image 1 layout with colored top borders */}
      {loading ? (
        <div style={{ display:'flex', gap:12 }}>
          {[1,2,3,4,5].map(i=><div key={i} style={{ flex:1, height:120, background:'#fff', borderRadius:14, border:'1px solid #e8e8f0' }}/>)}
        </div>
      ) : (
        <>
          <div style={{ display:'grid', gridTemplateColumns:'repeat(5,1fr)', gap:14, marginBottom:14 }}>
            {STATS_DEF.slice(0,5).map((s,i) => (
              <StatCard key={i} {...s}/>
            ))}
          </div>
          <div style={{ display:'grid', gridTemplateColumns:'repeat(5,1fr)', gap:14, marginBottom:32 }}>
            <StatCard {...STATS_DEF[5]}/>
          </div>

          {/* Tables row */}
          <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:16, marginBottom:16 }}>
            {/* Recent Exams */}
            <div style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:14, overflow:'hidden', boxShadow:'0 1px 3px rgba(0,0,0,.05)' }}>
              <div style={{ padding:'14px 20px', borderBottom:'1px solid #f3f4f6', display:'flex', justifyContent:'space-between', alignItems:'center' }}>
                <span style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:14, color:'#0f0f1a' }}>Recent Exams</span>
                <button onClick={()=>setActivePage('exams')} style={{ fontSize:12, fontWeight:600, color:'#7c3aed', background:'none', border:'none', cursor:'pointer' }}>View All →</button>
              </div>
              {stats.exams.length===0 ? <div className="empty-state" style={{padding:32}}><div className="empty-icon">📋</div><div className="empty-sub">No exams yet</div></div> : (
                <table style={{width:'100%',borderCollapse:'collapse'}}>
                  <thead><tr style={{background:'#f8f8fc'}}>{['TITLE','QUESTIONS','DURATION','STATUS'].map(h=><th key={h} style={{padding:'9px 16px',textAlign:'left',fontSize:9,fontWeight:700,color:'#9ca3af',textTransform:'uppercase',letterSpacing:1.5,fontFamily:'JetBrains Mono,monospace',borderBottom:'1px solid #f3f4f6'}}>{h}</th>)}</tr></thead>
                  <tbody>{stats.exams.slice(0,5).map(e=>(
                    <tr key={e.exam_id} style={{borderBottom:'1px solid #f3f4f6'}} onMouseEnter={el=>el.currentTarget.style.background='#f8f8fc'} onMouseLeave={el=>el.currentTarget.style.background='transparent'}>
                      <td style={{padding:'11px 16px',fontWeight:600,color:'#0f0f1a',fontSize:13}}>{e.title}</td>
                      <td style={{padding:'11px 16px',fontSize:12,color:'#6b7280',fontFamily:'JetBrains Mono,monospace'}}>{stats.qCounts[e.exam_id]||0}</td>
                      <td style={{padding:'11px 16px',fontSize:12,color:'#6b7280',fontFamily:'JetBrains Mono,monospace'}}>{e.duration_minutes}m</td>
                      <td style={{padding:'11px 16px'}}><span style={{padding:'2px 8px',borderRadius:4,fontSize:10,fontWeight:700,background:e.status==='published'?'#dcfce7':'#fef3c7',color:e.status==='published'?'#16a34a':'#d97706'}}>{e.status==='published'?'Published':'Draft'}</span></td>
                    </tr>
                  ))}</tbody>
                </table>
              )}
            </div>
            {/* Recent Submissions */}
            <div style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:14, overflow:'hidden', boxShadow:'0 1px 3px rgba(0,0,0,.05)' }}>
              <div style={{ padding:'14px 20px', borderBottom:'1px solid #f3f4f6', display:'flex', justifyContent:'space-between', alignItems:'center' }}>
                <span style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:14, color:'#0f0f1a' }}>Recent Submissions</span>
                <button onClick={()=>setActivePage('analytics')} style={{ fontSize:12, fontWeight:600, color:'#7c3aed', background:'none', border:'none', cursor:'pointer' }}>Analytics →</button>
              </div>
              {stats.subs.length===0 ? <div className="empty-state" style={{padding:32}}><div className="empty-icon">📄</div><div className="empty-sub">No submissions yet</div></div> : (
                <table style={{width:'100%',borderCollapse:'collapse'}}>
                  <thead><tr style={{background:'#f8f8fc'}}>{['STUDENT','EXAM','SCORE','GRADE'].map(h=><th key={h} style={{padding:'9px 16px',textAlign:'left',fontSize:9,fontWeight:700,color:'#9ca3af',textTransform:'uppercase',letterSpacing:1.5,fontFamily:'JetBrains Mono,monospace',borderBottom:'1px solid #f3f4f6'}}>{h}</th>)}</tr></thead>
                  <tbody>{stats.subs.slice(0,6).map(sub=>{const gc=sub.grade==='A+'||sub.grade==='A'?'#16a34a':sub.grade==='F'?'#dc2626':'#d97706';return(
                    <tr key={sub.submission_id} style={{borderBottom:'1px solid #f3f4f6'}} onMouseEnter={e=>e.currentTarget.style.background='#f8f8fc'} onMouseLeave={e=>e.currentTarget.style.background='transparent'}>
                      <td style={{padding:'10px 16px',fontWeight:600,color:'#0f0f1a',fontSize:13}}>{sub.student_name||'—'}</td>
                      <td style={{padding:'10px 16px',fontSize:12,color:'#6b7280'}}>{sub.exam_title?.slice(0,16)||'—'}</td>
                      <td style={{padding:'10px 16px',fontSize:12,fontFamily:'JetBrains Mono,monospace'}}>{sub.total_score!=null?`${Number(sub.total_score).toFixed(0)}/${sub.total_marks}`:'—'}</td>
                      <td style={{padding:'10px 16px'}}>{sub.grade?<span style={{padding:'2px 8px',borderRadius:4,background:`${gc}15`,color:gc,fontSize:10,fontWeight:800}}>{sub.grade}</span>:'—'}</td>
                    </tr>
                  );})}
                  </tbody>
                </table>
              )}
            </div>
          </div>

          {/* Quick actions */}
          <div style={{ display:'grid', gridTemplateColumns:'repeat(4,1fr)', gap:12 }}>
            {[
              { icon:'📝', title:'Create Exam', desc:'Build AI-powered exams', color:'#ede9fe', border:'#ddd6fe', tc:'#7c3aed', page:'create-exam' },
              { icon:'👥', title:'View Students', desc:'Monitor performance', color:'#dbeafe', border:'#bfdbfe', tc:'#2563eb', page:'students' },
              { icon:'📊', title:'Analytics', desc:'Deep dive into data', color:'#dcfce7', border:'#bbf7d0', tc:'#16a34a', page:'analytics' },
              { icon:'📢', title:'Announcements', desc:'Post updates to all', color:'#fef3c7', border:'#fde68a', tc:'#d97706', page:'notifications' },
            ].map((q,i) => (
              <div key={i} onClick={()=>setActivePage(q.page)}
                style={{ background:q.color, border:`1px solid ${q.border}`, borderRadius:12, padding:16, cursor:'pointer', transition:'all .2s' }}
                onMouseEnter={e=>{e.currentTarget.style.transform='translateY(-2px)';e.currentTarget.style.boxShadow=`0 6px 20px ${q.border}`;}}
                onMouseLeave={e=>{e.currentTarget.style.transform='translateY(0)';e.currentTarget.style.boxShadow='none';}}>
                <div style={{ fontSize:22, marginBottom:8 }}>{q.icon}</div>
                <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:13, color:'#0f0f1a', marginBottom:3 }}>{q.title}</div>
                <div style={{ fontSize:11, color:'#6b7280' }}>{q.desc}</div>
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

function StatCard({ label, value, sub, color }) {
  return (
    <div style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:12, padding:'18px 20px', position:'relative', overflow:'hidden', boxShadow:'0 1px 3px rgba(0,0,0,.05)' }}>
      <div style={{ position:'absolute', top:0, left:0, right:0, height:3, background:color }}/>
      <div style={{ fontSize:10, fontWeight:700, textTransform:'uppercase', letterSpacing:1.5, color:'#9ca3af', marginBottom:12, fontFamily:'JetBrains Mono,monospace' }}>{label}</div>
      <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:900, fontSize:28, color:'#0f0f1a', lineHeight:1, marginBottom:8 }}>{value}</div>
      <div style={{ fontSize:12, color:'#9ca3af' }}>{sub}</div>
    </div>
  );
}
